function Assert-PhaseBExactProperties([object]$Value,[string[]]$Expected,[string]$Reason){$actual=@($Value.PSObject.Properties.Name|Sort-Object);$wanted=@($Expected|Sort-Object);if(($actual-join[char]0)-cne($wanted-join[char]0)){throw $Reason}}
function ConvertTo-PhaseBCanonicalJson([object]$Value){return($Value|ConvertTo-Json -Depth 40 -Compress)}
function Get-PhaseBSha([byte[]]$Bytes){$h=[Security.Cryptography.SHA256]::Create();try{return([BitConverter]::ToString($h.ComputeHash($Bytes)).Replace('-','').ToLowerInvariant())}finally{$h.Dispose()}}
function Get-PhaseBPublicFingerprint([byte[]]$PublicBytes){$text=[Text.Encoding]::ASCII.GetString($PublicBytes).Trim();$parts=$text-split'\s+';if($parts.Count-lt2-or$parts[0]-cne'ssh-ed25519'){throw 'RECEIPT_PUBLIC_KEY_INVALID'};return Get-PhaseBSha ([Convert]::FromBase64String($parts[1]))}

