 [string]$SignerIdentity,[string]$ReceiptPublicFingerprint,[string]$ReceiptPrivateKeyPath,[string]$SshKeygenPath,[string]$SshKeygenSha256,[string]$Namespace=$script:PhaseBNamespace,
 [string]$GenerationId='',[ValidateRange(1,[long]::MaxValue)][long]$Sequence=1,[string]$PredecessorGenerationId=('0'*32)){
 $null=Assert-OperatorPinnedFile $SshKeygenPath $SshKeygenSha256 'SSH_KEYGEN_IDENTITY_MISMATCH';$policyBytes=Read-OperatorPinnedBytes $RuntimeAclPolicyPath $RuntimeAclPolicySha256 'ACL_POLICY_IDENTITY_MISMATCH';$policyRaw=[Text.UTF8Encoding]::new($false,$true).GetString($policyBytes);if(-not$policyRaw.EndsWith("`n")){throw 'ACL_POLICY_NOT_CANONICAL'};$aclPolicy=$policyRaw|ConvertFrom-Json;if((ConvertTo-PhaseBCanonicalJson $aclPolicy)+"`n"-cne$policyRaw){throw 'ACL_POLICY_NOT_CANONICAL'};Assert-OperatorRestrictedAcl $ReceiptPrivateKeyPath
