'};if(@($ConfigAndKeyFingerprints.files).Count+@($ConfigAndKeyFingerprints.private_keys).Count+@($ConfigAndKeyFingerprints.public_keys).Count-eq0){throw 'CONFIG_KEY_TOPOLOGY_EMPTY'};foreach($item in @($ConfigAndKeyFingerprints.public_keys)){Assert-PhaseBExactProperties $item @('file_sha256','fingerprint_sha256','path') 'CONFIG_KEY_TOPOLOGY_INVALID'}
 $enrollmentPaths=@($MutablePaths|ForEach-Object{[string]$_.enrollment_path}|Sort-Object -Unique);if($enrollmentPaths.Count-gt1){throw 'MUTABLE_ENROLLMENT_TOPOLOGY_INVALID'};foreach($item in @($MutablePaths)){Assert-PhaseBExactProperties $item @('enrollment_nonce','enrollment_path','initial_state','path','protected_parent_policy_entry') 'MUTABLE_TOPOLOGY_INVALID';Assert-PhaseBExactProperties $item.initial_state @('kind','schema_version') 'MUTABLE_TOPOLOGY_INVALID';if((Test-Path -LiteralPath $item.path)-or(Test-Path -LiteralPath $item.enrollment_path)){throw 'MUTABLE_EXPECTED_ABSENT'};if($item.initial_state.kind-notin@('absent_then_canonical_schema','activation_challenge')-or[string]::IsNullOrEmpty([string]$item.enrollment_nonce)){throw 'MUTABLE_TOPOLOGY_INVALID'};$parent=[IO.Path]::GetDirectoryName([string]$item.path);if([IO.Path]::GetDirectoryName([string]$item.enrollment_path)-cne$parent){throw 'MUTABLE_TOPOLOGY_INVALID'};$record=@($aclPolicy.records|Where-Object{$_.path-ceq$parent});if($record.Count-ne1-or(($record[0]|ConvertTo-Json -Depth 20 -Compress)-cne($item.protected_parent_policy_entry|ConvertTo-Json -Depth 20 -Compress))){throw 'MUTABLE_PARENT_POLICY_BINDING_INVALID'}}
 $payload=[ordered]@{config_and_key_fingerprints=$ConfigAndKeyFingerprints;dependency_topology=$DependencyTopology;firewall_topology=$FirewallTopology;immutable_files=@($ImmutableFiles|Sort-Object path);mutable_paths=@($MutablePaths|Sort-Object path);receipt_namespace=$Namespace;receipt_public_fingerprint=$ReceiptPublicFingerprint;receipt_signer_identity=$SignerIdentity;runtime_acl_policy=[ordered]@{path=[IO.Path]::GetFullPath($RuntimeAclPolicyPath);sha256=$RuntimeAclPolicySha256};schema_version=$script:PhaseBReceiptSchema;task_topology=$TaskTopology}
