 $generationRoot=$pointer+'.generations';if([string]::IsNullOrEmpty($GenerationId)){$GenerationId=[Guid]::NewGuid().ToString('N')};if($GenerationId-cnotmatch'^[0-9a-f]{32}$'-or$PredecessorGenerationId-cnotmatch'^[0-9a-f]{32}$'-or($Sequence-eq1-and$PredecessorGenerationId-cne('0'*32))-or($Sequence-gt1-and$PredecessorGenerationId-ceq('0'*32))){throw 'PRECOMMIT_SEQUENCE_INVALID'};$generationId=$GenerationId;$generationDirectory=Join-Path $generationRoot $generationId
