  $null=[IO.Directory]::CreateDirectory($generationDirectory)
  [IO.File]::WriteAllText($generationReceipt,$json,[Text.UTF8Encoding]::new($false));& $SshKeygenPath -Y sign -f $ReceiptPrivateKeyPath -n $Namespace $generationReceipt|Out-Null
  if($LASTEXITCODE-ne0-or-not(Test-Path -LiteralPath $generationSignature)){throw 'RECEIPT_SIGN_FAILED'}
  $current=[ordered]@{generation_id=$generationId;predecessor_generation_id=$PredecessorGenerationId;receipt_sha256=(Get-FileHash -LiteralPath $generationReceipt -Algorithm SHA256).Hash.ToLowerInvariant();schema_version='finex-operator-receipt-current-payload-v2';sequence=$Sequence;signature_sha256=(Get-FileHash -LiteralPath $generationSignature -Algorithm SHA256).Hash.ToLowerInvariant()};$pointerPayloadJson=(ConvertTo-PhaseBCanonicalJson $current)+"`n";[IO.File]::WriteAllText($pointerPayloadTemp,$pointerPayloadJson,[Text.UTF8Encoding]::new($false));& $SshKeygenPath -Y sign -f $ReceiptPrivateKeyPath -n ($Namespace+'-pointer') $pointerPayloadTemp|Out-Null;if($LASTEXITCODE-ne0-or-not(Test-Path -LiteralPath ($pointerPayloadTemp+'.sig'))){throw 'POINTER_SIGN_FAILED'};$pointerEnvelope=[ordered]@{payload=$current;schema_version='finex-operator-receipt-current-envelope-v2';signature_base64=[Convert]::ToBase64String([IO.File]::ReadAllBytes($pointerPayloadTemp+'.sig'))}
  [IO.File]::WriteAllText($pointerTemp,(ConvertTo-PhaseBCanonicalJson $pointerEnvelope)+"`n",[Text.UTF8Encoding]::new($false));Move-Item -LiteralPath $pointerTemp -Destination $pointer -ErrorAction Stop;$committed=$true
