 }catch{if(-not$committed-and(Test-Path -LiteralPath $generationDirectory)){Remove-Item -LiteralPath $generationDirectory -Recurse -Force -ErrorAction SilentlyContinue};throw}
 finally{Remove-Item -LiteralPath $pointerTemp,$pointerPayloadTemp,($pointerPayloadTemp+'.sig') -Force -ErrorAction SilentlyContinue}
