function New-PhaseBPrecommitPlan(
 [string]$PrecommitRoot,[string]$FuturePointerPath,[string]$GenerationId,[long]$Sequence,[string]$PredecessorGenerationId,
 [array]$ImmutableFiles,[array]$MutablePaths,[string]$RuntimeAclPolicyPath,[string]$RuntimeAclPolicySha256,
 [object]$DependencyTopology,[object]$TaskTopology,[object]$FirewallTopology,[object]$ConfigAndKeyFingerprints,
 [string]$SignerIdentity,[string]$ReceiptPublicFingerprint,[string]$ReceiptPrivateKeyPath,[string]$SshKeygenPath,[string]$SshKeygenSha256,[ValidateSet('finex-cas','finex-fetcher','putra-producer')][string]$OperatorRole,[string]$Namespace=$script:PhaseBNamespace){
 if(-not[IO.Path]::IsPathRooted($PrecommitRoot)-or-not[IO.Path]::IsPathRooted($FuturePointerPath)){throw 'PRECOMMIT_PATH_INVALID'}
 if(Test-Path -LiteralPath $PrecommitRoot){throw 'PRECOMMIT_COLLISION'};if(Test-Path -LiteralPath $FuturePointerPath){throw 'FUTURE_POINTER_MUST_BE_ABSENT'}
 if($TaskTopology.phase-cne'installed-disabled'-or$TaskTopology.trigger_count-ne0-or$TaskTopology.live_definition.state-cne'Disabled'){throw 'PRECOMMIT_TOPOLOGY_NOT_INSTALLED_DISABLED'}
 $parent=Split-Path ([IO.Path]::GetFullPath($PrecommitRoot)) -Parent;$stage=Join-Path $parent ('.phase-b-precommit-'+$GenerationId);$committed=$false
 try{
  [IO.Directory]::CreateDirectory($stage)|Out-Null;$stagePointer=Join-Path $stage 'current.json'
  $result=New-PhaseBSignedReceipt $stagePointer $ImmutableFiles $MutablePaths $RuntimeAclPolicyPath $RuntimeAclPolicySha256 $DependencyTopology $TaskTopology $FirewallTopology $ConfigAndKeyFingerprints $SignerIdentity $ReceiptPublicFingerprint $ReceiptPrivateKeyPath $SshKeygenPath $SshKeygenSha256 $Namespace $GenerationId $Sequence $PredecessorGenerationId
  $pointerSha=(Get-FileHash -LiteralPath $stagePointer -Algorithm SHA256).Hash.ToLowerInvariant()
  $manifest=[ordered]@{future_pointer_path=[IO.Path]::GetFullPath($FuturePointerPath);generation_id=$GenerationId;generation_receipt_sha256=$result.receipt_sha256;generation_signature_sha256=$result.signature_sha256;operator_role=$OperatorRole;pointer_sha256=$pointerSha;predecessor_generation_id=$PredecessorGenerationId;receipt_namespace=$Namespace;receipt_public_fingerprint=$ReceiptPublicFingerprint;receipt_signer_identity=$SignerIdentity;schema_version='finex-phase-b-precommit-plan-v1';sequence=$Sequence;task_topology_sha256=Get-OperatorTextSha256 (ConvertTo-PhaseBCanonicalJson $TaskTopology)}
  [IO.File]::WriteAllText((Join-Path $stage 'precommit.json'),(ConvertTo-PhaseBCanonicalJson $manifest)+"`n",[Text.UTF8Encoding]::new($false))
  Move-Item -LiteralPath $stage -Destination ([IO.Path]::GetFullPath($PrecommitRoot)) -ErrorAction Stop;$committed=$true
  return [ordered]@{generation_id=$GenerationId;manifest_path=Join-Path ([IO.Path]::GetFullPath($PrecommitRoot)) 'precommit.json';pointer_path=Join-Path ([IO.Path]::GetFullPath($PrecommitRoot)) 'current.json';pointer_sha256=$pointerSha;sequence=$Sequence}
 }finally{if(-not$committed-and(Test-Path -LiteralPath $stage)){Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue}}
}
